python3 -c "
import re

def clean_term(term):
    term = re.sub(r'^[^a-zA-Z0-9]+', '', term)
    term = re.sub(r'[^a-zA-Z0-9]+$', '', term)
    return term

def highlight_title(title, query):
    terms = [clean_term(t) for t in query.split()]
    terms = [t for t in terms if t]
    if not terms:
        return title

    intervals = []
    for term in terms:
        pattern = re.compile(rf'(?<![a-zA-Z0-9])({re.escape(term)})(?![a-zA-Z0-9])', re.IGNORECASE)
        for m in pattern.finditer(title):
            intervals.append((m.start(), m.end()))

    if not intervals:
        return title

    intervals.sort(key=lambda x: (x[0], -x[1]))
    merged = []
    for start, end in intervals:
        if not merged:
            merged.append((start, end))
        else:
            last_start, last_end = merged[-1]
            if start <= last_end:
                merged[-1] = (last_start, max(last_end, end))
            else:
                merged.append((start, end))

    highlighted = []
    last_idx = 0
    for start, end in merged:
        highlighted.append(title[last_idx:start])
        highlighted.append('<b>')
        highlighted.append(title[start:end])
        highlighted.append('</b>')
        last_idx = end
    highlighted.append(title[last_idx:])
    return ''.join(highlighted)

print(highlight_title('Canary rollout guide for the payments API', 'canary payments'))
print(highlight_title('Canary rollout guide for the payments API', 'can'))
print(highlight_title('Canary rollout guide for the payments API', 'api'))
"

